-- Transfer principal amounts are the actual debited and received amounts.
CREATE TABLE transfer_details (
 transaction_id TEXT PRIMARY KEY NOT NULL, household_id TEXT NOT NULL,
 from_account_id TEXT NOT NULL, to_account_id TEXT NOT NULL,
 debit_amount_minor INTEGER NOT NULL CHECK(typeof(debit_amount_minor)='integer' AND debit_amount_minor BETWEEN 1 AND 9007199254740991),
 credit_amount_minor INTEGER NOT NULL CHECK(typeof(credit_amount_minor)='integer' AND credit_amount_minor BETWEEN 1 AND 9007199254740991),
 debit_currency TEXT NOT NULL, credit_currency TEXT NOT NULL, fee_transaction_id TEXT,
 CHECK(from_account_id<>to_account_id),
 CHECK(debit_currency<>credit_currency OR debit_amount_minor=credit_amount_minor),
 FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id),
 FOREIGN KEY(household_id,from_account_id,debit_currency) REFERENCES accounts(household_id,id,currency),
 FOREIGN KEY(household_id,to_account_id,credit_currency) REFERENCES accounts(household_id,id,currency),
 FOREIGN KEY(household_id,fee_transaction_id) REFERENCES transactions(household_id,id)
);
CREATE UNIQUE INDEX transfer_details_fee_idx ON transfer_details(household_id,fee_transaction_id) WHERE fee_transaction_id IS NOT NULL;

-- Consumers sum signed movements. Principal transfers and non-transaction account
-- movements are excluded; a fee appears once as its own expense transaction.
CREATE VIEW transaction_reporting_movements AS
 SELECT t.household_id,t.id AS transaction_id,t.type,t.transaction_date,t.category_id,
        m.id AS movement_id,m.account_id,m.amount_minor,m.currency,m.rsd_equivalent_minor
 FROM transactions t JOIN account_movements m ON m.household_id=t.household_id AND m.transaction_id=t.id
 WHERE t.status='posted' AND t.type IN ('expense','income','fee','refund') AND m.type='transaction';

-- All parameters are bound; amount fields in expected_json are decimal strings.
CREATE VIEW transfer_checks AS SELECT NULL AS household_id,NULL AS member_id,NULL AS transaction_id,NULL AS version,NULL AS operation,NULL AS expected_json WHERE 0;
CREATE TRIGGER transfer_checks_insert INSTEAD OF INSERT ON transfer_checks BEGIN
 SELECT CASE WHEN NEW.operation NOT IN ('post','edit','void') OR NOT EXISTS (SELECT 1 FROM household_members m JOIN households h ON h.id=m.household_id WHERE m.household_id=NEW.household_id AND m.id=NEW.member_id AND m.status='active' AND h.status='active') THEN RAISE(ABORT,'transfer_member_ineligible') END;
 SELECT CASE WHEN NEW.operation<>'post' AND NOT EXISTS (SELECT 1 FROM transactions t JOIN transfer_details d ON d.household_id=t.household_id AND d.transaction_id=t.id WHERE t.household_id=NEW.household_id AND t.id=NEW.transaction_id AND t.type='transfer' AND t.status='posted' AND t.version=NEW.version AND t.version<9007199254740991) THEN RAISE(ABORT,'transfer_version_conflict') END;
 SELECT CASE WHEN NEW.operation<>'post' AND (EXISTS(SELECT 1 FROM reserve_movements WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id) OR EXISTS(SELECT 1 FROM import_drafts WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id) OR EXISTS(SELECT 1 FROM receipt_items WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id) OR EXISTS(SELECT 1 FROM import_references WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id)) THEN RAISE(ABORT,'transfer_linked') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM account_movements m JOIN accounts a ON a.household_id=m.household_id AND a.id=m.account_id WHERE m.household_id=NEW.household_id AND (m.transaction_id=NEW.transaction_id OR m.transaction_id IN (SELECT id FROM transactions WHERE household_id=NEW.household_id AND parent_transaction_id=NEW.transaction_id AND type='fee' AND status='posted')) AND a.status<>'active') THEN RAISE(ABORT,'transfer_account_ineligible') END;
 SELECT CASE WHEN NEW.operation<>'void' AND (json_extract(NEW.expected_json,'$.fromAccountId') IS json_extract(NEW.expected_json,'$.toAccountId') OR NOT EXISTS(SELECT 1 FROM accounts WHERE household_id=NEW.household_id AND id=json_extract(NEW.expected_json,'$.fromAccountId') AND currency=json_extract(NEW.expected_json,'$.debitCurrency') AND status='active') OR NOT EXISTS(SELECT 1 FROM accounts WHERE household_id=NEW.household_id AND id=json_extract(NEW.expected_json,'$.toAccountId') AND currency=json_extract(NEW.expected_json,'$.creditCurrency') AND status='active')) THEN RAISE(ABORT,'transfer_account_ineligible') END;
 SELECT CASE WHEN NEW.operation<>'void' AND (CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR (json_extract(NEW.expected_json,'$.debitCurrency')=json_extract(NEW.expected_json,'$.creditCurrency') AND CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER)<>CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER))) THEN RAISE(ABORT,'transfer_amount_invalid') END;
 SELECT CASE WHEN NEW.operation<>'void' AND json_type(NEW.expected_json,'$.fee')='object' AND (CAST(json_extract(NEW.expected_json,'$.fee.amountMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR NOT EXISTS(SELECT 1 FROM categories WHERE household_id=NEW.household_id AND id=json_extract(NEW.expected_json,'$.fee.categoryId') AND type='expense' AND status='active')) THEN RAISE(ABORT,'transfer_fee_invalid') END;
 -- Removing every old principal and current fee before applying the new legs
 -- covers swaps, overlapping accounts, spent credits and reserved balances.
 SELECT CASE WHEN EXISTS(SELECT 1 FROM accounts a WHERE a.household_id=NEW.household_id AND (a.id IN (json_extract(NEW.expected_json,'$.fromAccountId'),json_extract(NEW.expected_json,'$.toAccountId')) OR a.id IN (SELECT account_id FROM account_movements WHERE household_id=NEW.household_id AND (transaction_id=NEW.transaction_id OR transaction_id IN (SELECT id FROM transactions WHERE household_id=NEW.household_id AND parent_transaction_id=NEW.transaction_id AND type='fee' AND status='posted')))) AND (
 (SELECT COALESCE(SUM(amount_minor),0) FROM account_movements m WHERE m.household_id=a.household_id AND m.account_id=a.id AND (m.transaction_id IS NULL OR (m.transaction_id<>NEW.transaction_id AND m.transaction_id NOT IN (SELECT id FROM transactions WHERE household_id=NEW.household_id AND parent_transaction_id=NEW.transaction_id AND type='fee' AND status='posted'))))
 + CASE WHEN NEW.operation<>'void' AND a.id=json_extract(NEW.expected_json,'$.fromAccountId') THEN -CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER)-COALESCE(CAST(json_extract(NEW.expected_json,'$.fee.amountMinor') AS INTEGER),0) ELSE 0 END
 + CASE WHEN NEW.operation<>'void' AND a.id=json_extract(NEW.expected_json,'$.toAccountId') THEN CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER) ELSE 0 END
 - (SELECT COALESCE(SUM(amount_minor),0) FROM reserve_movements r WHERE r.household_id=a.household_id AND r.account_id=a.id)<0 OR
 (SELECT COALESCE(SUM(amount_minor),0) FROM account_movements m WHERE m.household_id=a.household_id AND m.account_id=a.id AND (m.transaction_id IS NULL OR (m.transaction_id<>NEW.transaction_id AND m.transaction_id NOT IN (SELECT id FROM transactions WHERE household_id=NEW.household_id AND parent_transaction_id=NEW.transaction_id AND type='fee' AND status='posted'))))
 + CASE WHEN NEW.operation<>'void' AND a.id=json_extract(NEW.expected_json,'$.fromAccountId') THEN -CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER)-COALESCE(CAST(json_extract(NEW.expected_json,'$.fee.amountMinor') AS INTEGER),0) ELSE 0 END
 + CASE WHEN NEW.operation<>'void' AND a.id=json_extract(NEW.expected_json,'$.toAccountId') THEN CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER) ELSE 0 END > 9007199254740991)) THEN RAISE(ABORT,'transfer_balance_invalid') END;
END;

CREATE VIEW transfer_result_checks AS SELECT NULL AS household_id,NULL AS transaction_id,NULL AS version,NULL AS operation,NULL AS expected_json,NULL AS fee_id,NULL AS fee_rsd,NULL AS audit_id,NULL AS claim_id WHERE 0;
CREATE TRIGGER transfer_result_checks_insert INSTEAD OF INSERT ON transfer_result_checks BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM transactions t JOIN transfer_details d ON d.household_id=t.household_id AND d.transaction_id=t.id WHERE t.household_id=NEW.household_id AND t.id=NEW.transaction_id AND t.type='transfer' AND t.version=NEW.version AND t.status=CASE WHEN NEW.operation='void' THEN 'void' ELSE 'posted' END AND (NEW.operation='void' OR (t.transaction_date IS json_extract(NEW.expected_json,'$.transactionDate') AND t.category_id IS NULL AND t.merchant IS json_extract(NEW.expected_json,'$.merchant') AND t.note IS json_extract(NEW.expected_json,'$.note') AND d.from_account_id IS json_extract(NEW.expected_json,'$.fromAccountId') AND d.to_account_id IS json_extract(NEW.expected_json,'$.toAccountId') AND d.debit_currency IS json_extract(NEW.expected_json,'$.debitCurrency') AND d.credit_currency IS json_extract(NEW.expected_json,'$.creditCurrency') AND d.debit_amount_minor=CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER) AND d.credit_amount_minor=CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER) AND d.fee_transaction_id IS NEW.fee_id))) THEN RAISE(ABORT,'transfer_result_invalid') END;
 SELECT CASE WHEN NEW.operation='void' AND EXISTS(SELECT 1 FROM account_movements WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id) OR NEW.operation<>'void' AND ((SELECT count(*) FROM account_movements WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id)<>2 OR NOT EXISTS(SELECT 1 FROM account_movements WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id AND type='transaction' AND account_id=json_extract(NEW.expected_json,'$.fromAccountId') AND currency=json_extract(NEW.expected_json,'$.debitCurrency') AND movement_date=json_extract(NEW.expected_json,'$.transactionDate') AND amount_minor=-CAST(json_extract(NEW.expected_json,'$.debitAmountMinor') AS INTEGER)) OR NOT EXISTS(SELECT 1 FROM account_movements WHERE household_id=NEW.household_id AND transaction_id=NEW.transaction_id AND type='transaction' AND account_id=json_extract(NEW.expected_json,'$.toAccountId') AND currency=json_extract(NEW.expected_json,'$.creditCurrency') AND movement_date=json_extract(NEW.expected_json,'$.transactionDate') AND amount_minor=CAST(json_extract(NEW.expected_json,'$.creditAmountMinor') AS INTEGER))) THEN RAISE(ABORT,'transfer_result_invalid') END;
 SELECT CASE WHEN NEW.operation<>'void' AND ((NEW.fee_id IS NOT NULL AND (NEW.fee_rsd IS NULL OR CAST(NEW.fee_rsd AS INTEGER) NOT BETWEEN 0 AND 9007199254740991)) OR (json_type(NEW.expected_json,'$.fee')='object') <> (NEW.fee_id IS NOT NULL) OR NEW.fee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM transactions f JOIN posting_details p ON p.household_id=f.household_id AND p.transaction_id=f.id WHERE f.household_id=NEW.household_id AND f.id=NEW.fee_id AND f.type='fee' AND f.parent_transaction_id=NEW.transaction_id AND f.status='posted' AND f.transaction_date=json_extract(NEW.expected_json,'$.transactionDate') AND f.category_id=json_extract(NEW.expected_json,'$.fee.categoryId') AND p.account_id=json_extract(NEW.expected_json,'$.fromAccountId') AND p.currency=json_extract(NEW.expected_json,'$.debitCurrency') AND p.amount_minor=CAST(json_extract(NEW.expected_json,'$.fee.amountMinor') AS INTEGER) AND p.rsd_equivalent_minor IS CAST(NEW.fee_rsd AS INTEGER) AND p.exchange_rate IS json_extract(NEW.expected_json,'$.fee.exchangeRate') AND p.exchange_rate_source IS json_extract(NEW.expected_json,'$.fee.exchangeRateSource') AND (SELECT count(*) FROM account_movements WHERE household_id=NEW.household_id AND transaction_id=f.id)=1 AND EXISTS(SELECT 1 FROM account_movements m WHERE m.household_id=f.household_id AND m.transaction_id=f.id AND m.type='transaction' AND m.account_id=p.account_id AND m.currency=p.currency AND m.movement_date=f.transaction_date AND m.amount_minor=-p.amount_minor AND m.rsd_equivalent_minor IS -p.rsd_equivalent_minor AND m.exchange_rate IS p.exchange_rate AND m.exchange_rate_source IS p.exchange_rate_source))) THEN RAISE(ABORT,'transfer_result_invalid') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM transactions f WHERE f.household_id=NEW.household_id AND f.parent_transaction_id=NEW.transaction_id AND f.type='fee' AND ((f.status='posted' AND (NEW.operation='void' OR f.id IS NOT NEW.fee_id)) OR (f.status='void' AND EXISTS(SELECT 1 FROM account_movements m WHERE m.household_id=f.household_id AND m.transaction_id=f.id)))) THEN RAISE(ABORT,'transfer_result_invalid') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM audit_events WHERE id=NEW.audit_id AND household_id=NEW.household_id AND transaction_id=NEW.transaction_id AND details_json IS NOT NULL AND (NEW.operation='post' OR (json_type(details_json,'$.before')='object' AND json_type(details_json,'$.after')='object' AND json_extract(details_json,'$.after.version')=NEW.version AND json_extract(details_json,'$.after.status')=CASE WHEN NEW.operation='void' THEN 'void' ELSE 'posted' END))) THEN RAISE(ABORT,'transfer_result_invalid') END;
 SELECT CASE WHEN NEW.operation='post' AND NOT EXISTS(SELECT 1 FROM posting_requests p JOIN idempotency_keys k ON k.household_id=p.household_id AND k.member_id=p.member_id AND k.request_key=p.request_key WHERE p.id=NEW.claim_id AND p.household_id=NEW.household_id AND p.response_json IS NOT NULL AND json_valid(p.response_json) AND json_extract(p.response_json,'$.id')=NEW.transaction_id AND json_extract(p.response_json,'$.householdId')=NEW.household_id AND json_extract(p.response_json,'$.type')='transfer' AND json_extract(p.response_json,'$.status')='posted' AND json_extract(p.response_json,'$.version')=NEW.version AND json_extract(p.response_json,'$.fromAccountId') IS json_extract(NEW.expected_json,'$.fromAccountId') AND json_extract(p.response_json,'$.toAccountId') IS json_extract(NEW.expected_json,'$.toAccountId') AND json_extract(p.response_json,'$.debitAmountMinor') IS json_extract(NEW.expected_json,'$.debitAmountMinor') AND json_extract(p.response_json,'$.creditAmountMinor') IS json_extract(NEW.expected_json,'$.creditAmountMinor') AND json_extract(p.response_json,'$.fee.id') IS NEW.fee_id AND k.transaction_id=NEW.transaction_id) THEN RAISE(ABORT,'transfer_result_invalid') END;
END;
